section.sourcecode:
apm-eat-binding = {
  eat_token_ref:    bstr,       ; hash of the referenced EAT token
  eat_hash_alg:     int / tstr, ; hash algorithm identifier
  claim_bindings:    [ *claim-binding ],
}

claim-binding = {
  posture_claim_id:  tstr,     ; APM posture claim identifier
  evidence_claim_id:  tstr,     ; EAT evidence claim identifier
  match_mode:        match-mode,
}

match-mode = &(
  exact:     0,
  threshold:  1,
  superset:   2,
)
